import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_ANGLE_RE = re.compile(r"<([^>]*)>")
_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)   # earliest marker wins
_NON_DIGIT_RE = re.compile(r"[^0-9]")
_OPTED_OUT_VALUES = {"y", "yes", "true", "1"}
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}


def _s(value):
    """Coerce a cell to a string ('' for None)."""
    return "" if value is None else str(value)


def _norm_email(raw):
    s = _s(raw)
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.split("+", 1)[0].replace(".", "")
            s = local + "@gmail.com"
    return s


def _email_valid(email):
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _norm_phone(raw):
    s = _s(raw)
    m = _EXT_RE.search(s)
    if m:
        s = s[: m.start()]
    digits = _NON_DIGIT_RE.sub("", s)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _phone_valid(phone):
    return len(phone) == 10 and phone[0] not in "01"


def _norm_zip(raw):
    z = _s(raw).strip()
    if "-" in z:  # ZIP+4
        z = z.split("-", 1)[0].strip()
    if re.fullmatch(r"[0-9]{4}", z):  # Excel ate the leading zero
        z = "0" + z
    return z if re.fullmatch(r"[0-9]{5}", z) else ""


def _norm_name(raw):
    n = _s(raw).strip()
    if n.isupper() or n.islower():
        n = n.title()
    return n


def _parse_updated(raw):
    s = _s(raw).strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _norm_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", _s(raw)) if t.strip()}


def _opted_out(raw):
    return _s(raw).strip().lower() in _OPTED_OUT_VALUES


def dedupe_contacts(rows):
    # ---- 1. Normalize every row; drop rows with no valid email AND no valid phone
    recs = []
    for idx, row in enumerate(rows):
        email = _norm_email(row.get("email"))
        if not _email_valid(email):
            email = ""
        phone = _norm_phone(row.get("phone"))
        if not _phone_valid(phone):
            phone = ""
        if not email and not phone:
            continue
        recs.append({
            "idx": idx,                      # position in original input
            "first_name": _norm_name(row.get("first_name")),
            "last_name": _norm_name(row.get("last_name")),
            "email": email,                  # "" unless valid
            "phone": phone,                  # "" unless valid
            "zip": _norm_zip(row.get("zip")),
            "tags": _norm_tags(row.get("tags")),
            "opted_out": _opted_out(row.get("opted_out")),
            "updated": _parse_updated(row.get("updated")),
            "source": _s(row.get("source")).strip().lower(),
        })

    # ---- 2. Union-find to group rows transitively
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)   # root is always the earliest row

    seen_email = {}
    seen_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in seen_email:
                union(i, seen_email[r["email"]])
            else:
                seen_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].casefold())
            if key in seen_phone_last:
                union(i, seen_phone_last[key])
            else:
                seen_phone_last[key] = i

    groups = {}  # root index -> list of recs; insertion order == earliest-row order
    for i, r in enumerate(recs):
        groups.setdefault(find(i), []).append(r)

    # ---- 3. Build one output dict per person
    def pick(group, field):
        candidates = [r for r in group if r[field]]
        if not candidates:
            return ""
        best = max(
            candidates,
            key=lambda r: (r["source"] == "manual", r["updated"], -r["idx"]),
        )
        return best[field]

    output = []
    for group in groups.values():
        tags = set()
        for r in group:
            tags |= r["tags"]
        output.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "email": pick(group, "email"),
            "phone": pick(group, "phone"),
            "zip": pick(group, "zip"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
            "source": pick(group, "source"),
        })
    return output
```

A few notes on choices where the rules left a little room:

- **`updated` parsing is strict.** If a value doesn't match one of the three formats, the function raises `ValueError` naming the bad value rather than silently guessing — better to find a broken row before the send than after. If you'd rather it skip those rows, swap the `raise` for `return None` and drop rows with `updated is None`.
- **Gmail validity after normalization:** something like `+promo@gmail.com` normalizes to an empty local part and is treated as invalid, per rule 2.
- **Extension markers:** the regex cuts at the earliest of `ext`, `x`, or `#`, so `555-123-4567 ext. 12` and `555-123-4567x12` both yield the 10 main digits.
- **ZIP+4:** anything with a hyphen keeps only the part before it, then the 4-digit/5-digit checks apply; so `2139-4307` → `02139`, and `123-4567` → `""`.
- **Ordering tie-break:** because union-find always makes the earliest row the root, groups come out in order of their earliest surviving row, and `pick()` prefers manual → latest `updated` → earliest input position.
- `None` cells are treated as `""` for safety even though your export shouldn't contain them.

